### Background and motivation

In .NET 6.0 preview five we have exposed the new Metrics APIs. In a couple of classes there we have exposed APIs which take tags parameters. 

```C#
namespace System.Diagnostics.Metrics
{
    public sealed class Counter<T> : Instrument<T> where T : struct
    {
        //
        // The following APIs takes individual tags to avoid memory allocations
        //
        public void Add(T delta, KeyValuePair<string, object?> tag);
        public void Add(T delta, KeyValuePair<string, object?> tag1, KeyValuePair<string, object?> tag2);
        public void Add(T delta, KeyValuePair<string, object?> tag1, KeyValuePair<string, object?> tag2, KeyValuePair<string, object?> tag3);

        //
        // The following API will allocate array object when passing more than three tags.
        //
        public void Add(T delta, params KeyValuePair<string, object?>[] tags);

        //
        // The following API to support using Span for scenarios whoever want to manually optimize how to store the tags without doing any more allocations.
        //
        public void Add(T delta, ReadOnlySpan<KeyValuePair<string, object?>> tags);
    }
}
```

We have been collecting the feedback regarding the Metrics APIs from the OpenTelemetry and other uses. We got the request to add more overloads which support up to eight tags. We have seen common scenarios that takes up to 8 tags. We need to ensure avoiding the allocation in such scenarios without requiring the users of these APIs to do more memory tracking from their side to optimize such calls.
The [OpenTelemetry Issue](https://github.com/open-telemetry/opentelemetry-dotnet/issues/2221) list some of this feedback.

### API Proposal

```C#
namespace System.Diagnostics
{
    public struct TagList :  IList< KeyValuePair<string, object?>>,  IReadOnlyList<KeyValuePair<string, object?>>
    {
        public TagList(ReadOnlySpan< KeyValuePair<string, object?>> tagList) : this() { throw null; }
        public readonly int Count => throw null;
        public readonly bool IsReadOnly => throw null;
        public KeyValuePair<string, object?> this[int index]
        {
            readonly get { { throw null; } }
            set { { throw null; } }
        }
        public void Add(string key, object? value) { throw null; }
        public void Add(KeyValuePair<string, object?> tag) { throw null; }
        public readonly void CopyTo(Span<KeyValuePair<string, object?>> tags) { throw null; }
        public void Insert(int index, KeyValuePair<string, object?> item) { throw null; }
        public void RemoveAt(int index) { throw null; }
        public void Clear() { throw null; }
        public readonly bool Contains(KeyValuePair<string, object?> item) { throw null; }
        public readonly void CopyTo(KeyValuePair<string, object?>[] array, int arrayIndex) { throw null; }
        public bool Remove(KeyValuePair<string, object?> item) { throw null; }
        public  readonly IEnumerator< KeyValuePair<string, object?>> GetEnumerator() { throw null; }
        readonly IEnumerator  IEnumerable.GetEnumerator() { throw null; }
        public readonly int IndexOf(KeyValuePair<string, object?> item) { throw null; }
        public struct Enumerator : IEnumerator<KeyValuePair<string, object?>>,  IEnumerator
        {
            public  KeyValuePair<string, object?> Current => throw null;
            object  IEnumerator.Current => throw null;
            public void Dispose() { throw null; }
            public bool MoveNext() { throw null; }
            public void Reset() { throw null; }
        }
    }
}

namespace System.Diagnostics.Metrics
{
    public sealed class Counter<T> : Instrument<T> where T : struct
    {
        public void Add(T delta, in TagList tagList) { throw null; }
    }

    public sealed class Histogram<T> : Instrument<T> where T : struct
    {
        public void Record(T value, in TagList tagList) { throw null; }
    }

    public abstract class Instrument<T> : Instrument where T : struct
    {
        protected void RecordMeasurement(T measurement, in TagList tagList) { throw null; }
    }
}

```


